"use client";
import {useEffect,useRef,useState,type ReactNode} from 'react';
import Link from 'next/link';
import {FontAwesomeIcon} from '@fortawesome/react-fontawesome';
import {faWallet,faLock,faArrowUpRightFromSquare,faArrowRight,faArrowDown,faArrowUp,faRotate,faDownload,faPlus,faXmark,faCheck,faClock,faShieldHalved,faTriangleExclamation,faPause,faPlay,faCircleCheck,faFileInvoice,faMagnifyingGlass,faSliders,faLink,faUserCheck,faArrowRightArrowLeft,faRobot,faBuilding,faCircleInfo} from '@fortawesome/free-solid-svg-icons';
import {useShared,sharedCommand,workspaceToken,refreshShared} from './shared-demo';
import {financeActors,contractBalance,contractLimits,pendingAmount,requiredApprovals,financeToday,toMajor,toMinor,type FinanceState,type FinanceContract,type FinanceRequest,type FinanceKind,type FinanceStatement} from '../lib/finance-model';
import {brickAction,readBrickUI,setBrickDraft,openBrick} from './brick-store';
const cash=(n:number)=>toMajor(n).toLocaleString('es-AR',{minimumFractionDigits:0,maximumFractionDigits:2})+' ARGt';
const short=(n:number)=>Math.abs(n)>=100000000?(toMajor(n)/1000000).toLocaleString('es-AR',{maximumFractionDigits:2})+' M':Math.abs(n)>=100000? (toMajor(n)/1000).toLocaleString('es-AR',{maximumFractionDigits:1})+' mil':toMajor(n).toLocaleString('es-AR',{maximumFractionDigits:2});
const date=(s:string)=>new Date(s.length===10?s+'T12:00:00Z':s).toLocaleDateString('es-AR',{day:'numeric',month:'short'});
const time=(s:string)=>new Date(s).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Argentina/Buenos_Aires'});
const tabs=[['overview','Visión general'],['contracts','Contratos y reservas'],['payments','Pagos y anticipos'],['movements','Movimientos'],['reconcile','Conciliación'],['beneficiaries','Beneficiarios'],['audit','Auditoría'],['rules','Reglas y conexión']];
type Selection={type:'contract'|'request'|'operation'|'fund'|'control'|'beneficiary'|'wallet'|'statement'|'movement';id?:string;kind?:FinanceKind;control?:'pause'|'dispute'|'cancelAdvance'|'source'};
const stateTone=(status:string)=>status==='Registrada'||status==='Conciliada'?'green':status==='Rechazada'||status==='Fallida'?'red':status==='Cancelada'?'neutral':'blue';
const contractStatus=(c:FinanceContract,s:FinanceState,now:string)=>c.disputed?'En disputa':c.paused?'Pausada':c.funded<c.principal?'Fondeo pendiente':contractBalance(c)===0?(c.refunded?'Cerrada con devolución':'Liquidada'):contractLimits(s,c,now).expired&&c.receivedValue<c.principal?'Plazo vencido':c.receivedValue>0&&c.receivedValue<c.principal?'Entrega parcial':'Activa';
function amountLimit(s:FinanceState,c:FinanceContract,kind:FinanceKind,now:string){const l=contractLimits(s,c,now);return kind==='Pago'?l.payment:kind==='Anticipo'?l.advance:kind==='Devolución'?l.refund:l.guarantee;}
function exportRows(name:string,rows:(string|number)[][]){const escaped=rows.map(row=>row.map(v=>'"'+(typeof v==='string'&&/^[=+@-]/.test(v)?"'"+v:String(v)).replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+escaped],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function FundsPage(){const {state,ready}=useShared();const s=state?.finance;const [tab,setTab]=useState('overview');const [actor,setActor]=useState('jm');const [project,setProject]=useState('');const [search,setSearch]=useState('');const [status,setStatus]=useState('Todas');const [kind,setKind]=useState('Todas');const [page,setPage]=useState(1);const [selection,setSelection]=useState<Selection|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [toast,setToast]=useState('');const [updated,setUpdated]=useState('');const [now,setNow]=useState('2026-11-04T00:00:00Z');const dialog=useRef<HTMLDialogElement>(null);const pending=useRef<{key:string;id:string}|null>(null);const appliedQuery=useRef(false);const readonly=!financeActors.find(a=>a.id===actor)?.operate;
 useEffect(()=>{setNow(new Date().toISOString());setUpdated(new Date().toISOString());const project=new URLSearchParams(location.search).get('proyecto');if(project)setProject(project);setActor(localStorage.getItem('oc-finance-actor-'+workspaceToken())||'jm');},[]);
 useEffect(()=>{setPage(1);},[project,search,status,tab,kind]);
 useEffect(()=>{if(selection){setError('');if(!dialog.current?.open)dialog.current?.showModal();}else dialog.current?.close();},[selection]);
 useEffect(()=>{if(!s||appliedQuery.current)return;const params=new URLSearchParams(location.search);const id=params.get('contrato');const c=s.contracts.find(c=>c.id===id||c.orderId===id);if(c){appliedQuery.current=true;setTab(params.get('accion')==='anticipo'?'payments':'contracts');setSelection(params.get('accion')==='anticipo'?{type:'operation',id:c.id,kind:'Anticipo'}:{type:'contract',id:c.id});}},[s]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(timer);},[toast]);
 function changeActor(id:string){setActor(id);localStorage.setItem('oc-finance-actor-'+workspaceToken(),id);}
 async function act(type:string,payload:Record<string,unknown>,keep=false){setBusy(true);setError('');const body={...payload,actor};const key=JSON.stringify({type,body});if(pending.current?.key!==key)pending.current={key,id:crypto.randomUUID()};try{await sharedCommand(type,body,pending.current.id);pending.current=null;setNow(new Date().toISOString());setUpdated(new Date().toISOString());if(!keep)setSelection(null);setToast(type==='finance.execute'?'Ejecución registrada en Obra Clara.':type==='finance.approve'?'Aprobación registrada.':'Cambio guardado con su registro de auditoría.');}catch(e){setError(e instanceof Error?e.message:'No se pudo registrar la operación.');}finally{setBusy(false);}}
 function askBrick(c:FinanceContract){brickAction('new');const ui=readBrickUI();if(ui.activeId)setBrickDraft(ui.activeId,{text:`Ayudame a revisar la reserva ${c.id} de ${c.project}, proveedor ${c.supplier}. Importe: ${cash(c.principal)}. Saldo de reserva: ${cash(contractBalance(c))}. Revisemos recepción, anticipo, aprobaciones y condiciones antes de emitir instrucciones.`,files:[]});setSelection(null);openBrick();}
 if(!ready||!s)return <section className="panel fn-loading"><FontAwesomeIcon icon={faWallet}/><h2>Preparando el control de fondos</h2><p>Cargando saldos, contratos, instrucciones y conciliación.</p></section>;
 const today=financeToday(now);const scope=s.contracts.filter(c=>!project||c.projectId===project);const scopedIds=new Set(scope.map(c=>c.id));const requests=s.requests.filter(r=>scopedIds.has(r.contractId));const activeRequests=requests.filter(r=>r.status==='Pendiente de aprobación'||r.status==='Aprobada');const awaiting=requests.filter(r=>r.status==='Pendiente de aprobación');const approved=requests.filter(r=>r.status==='Aprobada');const reserved=scope.reduce((n,c)=>n+contractBalance(c),0);const queued=activeRequests.reduce((n,r)=>n+r.amount,0);const releasable=scope.reduce((n,c)=>n+contractLimits(s,c,now).payment,0);const returnable=scope.reduce((n,c)=>n+contractLimits(s,c,now).refund,0);const retainage=scope.reduce((n,c)=>n+contractLimits(s,c,now).retained,0);const advanceExposed=scope.reduce((n,c)=>n+Math.max(0,c.advancePaid-c.receivedValue),0);const paidPeriod=scope.reduce((n,c)=>n+c.paid,0);const statementPending=s.statements.filter(row=>row.status==='Pendiente');const sourceMismatches=scope.filter(c=>c.live&&c.sourcePaid!==c.paid);const allProjects=[...new Map(s.contracts.map(c=>[c.projectId,c.project])).entries()];const contractRows=scope.filter(c=>(status==='Todas'||contractStatus(c,s,now)===status)&&(!search||`${c.orderId} ${c.project} ${c.supplier} ${c.item}`.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>(contractBalance(b)>0?1:0)-(contractBalance(a)>0?1:0)||b.createdAt.localeCompare(a.createdAt));const pages=Math.max(1,Math.ceil(contractRows.length/10));const currentPage=Math.min(page,pages);const movementRows=s.movements.filter(m=>!project||m.projectId===project).filter(m=>!search||`${m.reference} ${m.party} ${m.kind} ${m.orderId??''}`.toLowerCase().includes(search.toLowerCase()));const requestRows=requests.filter(r=>(status==='Todas'||r.status===status)&&(kind==='Todas'||r.kind===kind)&&(!search||`${r.id} ${r.reason} ${s.contracts.find(c=>c.id===r.contractId)?.supplier}`.toLowerCase().includes(search.toLowerCase())));const selectedContract=selection?.id?s.contracts.find(c=>c.id===selection.id):undefined;const selectedRequest=selection?.type==='request'?s.requests.find(r=>r.id===selection.id):undefined;const selectedStatement=selection?.type==='statement'?s.statements.find(r=>r.id===selection.id):undefined;const selectedBeneficiary=selection?.type==='beneficiary'?s.beneficiaries.find(b=>b.id===selection.id):undefined;const selectedMovement=selection?.type==='movement'?s.movements.find(m=>m.id===selection.id):undefined;
 function switchTab(value:string){setTab(value);setStatus('Todas');setSearch('');setKind('Todas');}
 function downloadStatement(){exportRows('obra-clara-estado-de-cuenta-'+today,[['Fecha','Movimiento','Orden','Contraparte','Importe ARGt','Impacto en cuenta ARGt','Referencia','Conciliado'],...movementRows.map(m=>[m.at,m.kind,m.orderId??'',m.party,toMajor(m.amount),toMajor(m.walletDelta),m.reference,m.reconciled?'Sí':'No'])]);setToast('Estado de cuenta descargado.');}
 const actorSelect=<label className="fn-actor"><span>Responsable de revisión</span><select aria-label="Responsable de revisión financiera" value={actor} onChange={e=>changeActor(e.target.value)}>{financeActors.map(a=><option key={a.id} value={a.id}>{a.name} · {a.role}</option>)}</select></label>;
 const requestTable=(rows:FinanceRequest[])=>rows.length?<div className="fn-table-scroll"><table className="fn-table"><thead><tr><th>Instrucción / orden</th><th>Proveedor / proyecto</th><th>Importe</th><th>Estado</th><th>Aprobaciones</th><th></th></tr></thead><tbody>{rows.map(r=>{const c=s.contracts.find(c=>c.id===r.contractId)!;return <tr key={r.id}><td><strong>{r.kind}</strong><small>{c.orderId} · {date(r.createdAt)}</small></td><td><strong>{c.supplier}</strong><small>{c.project}</small></td><td><strong>{cash(r.amount)}</strong></td><td><span className={'ov-tag '+stateTone(r.status)}>{r.status}</span></td><td><span className="fn-approval-count"><FontAwesomeIcon icon={faUserCheck}/>{r.approvals.length} / {requiredApprovals(s,r.amount)}</span></td><td><button className="fn-mini-button" onClick={()=>setSelection({type:'request',id:r.id})}>Revisar <FontAwesomeIcon icon={faArrowRight}/></button></td></tr>;})}</tbody></table></div>:<Empty text="No hay instrucciones con estos filtros."/>;
 return <div className="oc-funds"><section className="fn-toolbar"><div><span className="fn-eyebrow"><FontAwesomeIcon icon={faShieldHalved}/> TESORERÍA Y RESERVAS POR ORDEN</span><h2>Estado de cuenta</h2><p>Saldo disponible, reservas por orden y pagos pendientes.</p></div><div className="fn-top-actions"><button className="button secondary" onClick={downloadStatement}><FontAwesomeIcon icon={faDownload}/> Estado de cuenta</button><button className="button primary" onClick={()=>setSelection({type:'wallet'})}><FontAwesomeIcon icon={faPlus}/> Ingresar fondos</button></div></section><div className="fn-context"><label>Proyecto<select aria-label="Filtrar Fondos por proyecto" value={project} onChange={e=>setProject(e.target.value)}><option value="">Todos los proyectos</option>{allProjects.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label>{actorSelect}<span className="fn-synced"><i className="ov-dot green"/> Registros actualizados {updated?time(updated):'ahora'}</span><button className="fn-refresh" aria-label="Actualizar saldos e instrucciones" onClick={async()=>{await refreshShared();setUpdated(new Date().toISOString());setNow(new Date().toISOString());}}><FontAwesomeIcon icon={faRotate}/></button></div>{readonly&&<div className="fn-readonly"><FontAwesomeIcon icon={faLock}/> Perfil de auditoría: podés consultar y exportar; las instrucciones y cambios requieren un responsable habilitado.</div>}
 <nav className="fn-tabs" aria-label="Secciones de Fondos">{tabs.map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>switchTab(id)}>{label}{id==='payments'&&awaiting.length>0&&<span>{awaiting.length}</span>}{id==='reconcile'&&statementPending.length+sourceMismatches.length>0&&<span className="red">{statementPending.length+sourceMismatches.length}</span>}</button>)}</nav>
 {tab==='overview'&&<><section className="fn-metrics"><Metric label="Disponible en cuenta empresa" value={short(s.wallet)+' ARGt'} sub="Saldo para nuevas reservas" color="green" icon={faWallet} onClick={()=>setSelection({type:'wallet'})}/><Metric label="Saldo en contratos y reservas" value={short(reserved)+' ARGt'} sub={`${scope.filter(c=>contractBalance(c)>0).length} reservas con saldo`} color="blue" icon={faLock} onClick={()=>switchTab('contracts')}/><Metric label="Habilitado para pago manual" value={short(releasable)+' ARGt'} sub="Conformidad recibida, neto de instrucciones" color="green" icon={faCheck} onClick={()=>{switchTab('contracts');setStatus('Todas');}}/><Metric label="Instrucciones en aprobación" value={String(awaiting.length)} sub={`${short(queued)} ARGt comprometidos en cola`} color="blue" icon={faUserCheck} onClick={()=>switchTab('payments')}/><Metric label="Devolución habilitada" value={short(returnable)+' ARGt'} sub="Tramos no entregados fuera de plazo" color="red" icon={faArrowDown} onClick={()=>{switchTab('contracts');setStatus('Plazo vencido');}}/><Metric label="Diferencias por conciliar" value={String(statementPending.length+sourceMismatches.length)} sub="Extractos y pagos informados" color="red" icon={faFileInvoice} onClick={()=>switchTab('reconcile')}/></section>
 {(awaiting.length||approved.length||advanceExposed>0)&&<section className="fn-review-strip"><span className="fn-review-symbol"><FontAwesomeIcon icon={faTriangleExclamation}/></span><div><strong>{approved.length?`${approved.length} instrucciones listas para registrar`:awaiting.length+' instrucciones requieren aprobación'}</strong><p>{awaiting.length} en revisión · {short(advanceExposed)} ARGt de anticipos aún sin compensar con material recibido</p></div><button onClick={()=>switchTab('payments')}>Atender instrucciones <FontAwesomeIcon icon={faArrowRight}/></button></section>}
 <div className="fn-overview-grid"><section className="fn-wallet-card"><div className="fn-wallet-title"><span><FontAwesomeIcon icon={faWallet}/> Cuenta empresa</span><span className="fn-wallet-provider">belo</span></div><span className="fn-wallet-label">Disponible para nuevas reservas</span><strong className="fn-wallet-amount">{short(s.wallet)} <small>ARGt</small></strong><p>{s.settings.accountLabel}</p><div className="fn-wallet-assets"><div><span>Moneda operativa</span><strong>ARGt</strong></div><div><span>Red configurada</span><strong>{s.settings.network}</strong></div><div><span>Saldo externo Belo</span><strong>Sin lectura</strong></div></div><div className="fn-wallet-actions"><button onClick={()=>setSelection({type:'wallet'})}><FontAwesomeIcon icon={faArrowDown}/> Ingreso</button><button onClick={()=>setSelection({type:'wallet',id:'transfer'})}><FontAwesomeIcon icon={faArrowUp}/> Transferencia</button><button onClick={()=>setSelection({type:'wallet',id:'convert'})}><FontAwesomeIcon icon={faArrowRightArrowLeft}/> Conversión</button></div><button className="fn-wallet-connection" onClick={()=>switchTab('rules')}><i/> Vinculación de cuenta pendiente <FontAwesomeIcon icon={faArrowRight}/></button></section>
 <section className="ov-panel fn-capital"><Head title="Dónde está el capital" sub="Los importes en instrucción forman parte de las reservas"/><CapitalChart available={s.wallet} reserved={reserved} queued={queued}/><div className="fn-capital-summary"><div><span>Retenciones de garantía</span><strong>{cash(retainage)}</strong></div><div><span>Pagos registrados acumulados</span><strong>{cash(paidPeriod)}</strong></div><div><span>Instrucciones aprobadas</span><strong>{approved.length}</strong></div></div></section></div>
 <section className="ov-panel"><Head title="La próxima acción financiera" sub="Instrucciones creadas, aprobaciones faltantes y condiciones de la reserva"><button onClick={()=>switchTab('payments')}>Ver todas <FontAwesomeIcon icon={faArrowRight}/></button></Head>{requestTable(activeRequests.slice(0,5))}</section>
 <div className="fn-two-col"><section className="ov-panel"><Head title="Flujo de cuenta" sub="Ingresos y fondeos de reservas · últimos 7 días"/><CashFlow s={s} today={today}/></section><section className="ov-panel fn-deadlines"><Head title="Vencimientos y exposición" sub="Plazos de entrega, garantías y anticipos"/>{scope.filter(c=>contractBalance(c)>0).sort((a,b)=>(a.due||'z').localeCompare(b.due||'z')).slice(0,4).map(c=>{const l=contractLimits(s,c,now);return <button key={c.id} onClick={()=>setSelection({type:'contract',id:c.id})}><i className={'ov-dot '+(l.expired&&c.receivedValue<c.principal?'red':'blue')}/><span><strong>{c.orderId} · {c.project}</strong><small>{c.due?date(c.due):'Fecha pendiente'} · {c.supplier}</small></span><strong>{short(contractBalance(c))} ARGt</strong><FontAwesomeIcon icon={faArrowRight}/></button>;})}</section></div>
 <section className="ov-panel fn-finance-guides"><Head title="Cada acción tiene una condición" sub="Aprobación administrativa, registro y conciliación son estados distintos"/><div><article><span className="fn-guide-icon green"><FontAwesomeIcon icon={faCheck}/></span><h4>Pago por recepción</h4><p>Se habilita por cantidades conformadas, descontando pagos, anticipos compensados, retenciones e instrucciones pendientes.</p></article><article><span className="fn-guide-icon blue"><FontAwesomeIcon icon={faClock}/></span><h4>Anticipo acordado</h4><p>Se limita al porcentaje pactado. Puede cancelarse mientras no esté liquidado; lo ya pagado queda como exposición.</p></article><article><span className="fn-guide-icon red"><FontAwesomeIcon icon={faRotate}/></span><h4>Devolución de saldo</h4><p>Aplica al tramo no entregado, una vez cumplidas las condiciones de vencimiento y sin devolver dinero ya pagado al proveedor.</p></article></div></section></>}
 {tab==='contracts'&&<section className="ov-panel"><Head title="Contratos y reservas de fondos" sub="Orden, proyecto, beneficiario y reglas de liberación"><button disabled={readonly} onClick={()=>{const c=scope.find(c=>c.funded<c.principal);c?setSelection({type:'fund',id:c.id}):setToast('Todas las reservas seleccionadas ya tienen el fondeo completo.');}}><FontAwesomeIcon icon={faPlus}/> Asignar fondos</button></Head><div className="fn-table-controls"><Search value={search} onChange={setSearch} placeholder="Orden, proyecto, proveedor o material…"/><select aria-label="Estado de contratos y reservas" value={status} onChange={e=>setStatus(e.target.value)}>{['Todas','Activa','Entrega parcial','Plazo vencido','Fondeo pendiente','Pausada','En disputa','Liquidada','Cerrada con devolución'].map(v=><option key={v}>{v}</option>)}</select></div><div className="fn-table-scroll"><table className="fn-table"><thead><tr><th>Contrato / orden</th><th>Proyecto / proveedor</th><th>Importe / fondeado</th><th>Saldo de reserva</th><th>Habilitado</th><th>Estado</th><th></th></tr></thead><tbody>{contractRows.slice((currentPage-1)*10,currentPage*10).map(c=>{const l=contractLimits(s,c,now);const label=contractStatus(c,s,now);return <tr key={c.id}><td><strong>{c.orderId}</strong><small>{c.id}</small></td><td><strong>{c.project}</strong><small>{c.supplier}</small></td><td><strong>{cash(c.principal)}</strong><small>{cash(c.funded)} fondeados</small></td><td><strong>{cash(l.balance)}</strong><small>{short(l.pending)} ARGt en instrucciones</small></td><td><span className="fn-value-green">{short(l.payment)} ARGt</span><small>Pago por recepción</small></td><td><span className={'ov-tag '+(c.disputed||l.expired&&c.receivedValue<c.principal?'red':l.balance===0?'green':'blue')}>{label}</span></td><td><button className="fn-mini-button" onClick={()=>setSelection({type:'contract',id:c.id})}>Gestionar <FontAwesomeIcon icon={faArrowRight}/></button></td></tr>;})}</tbody></table>{!contractRows.length&&<Empty text="No hay contratos que coincidan con los filtros."/>}</div><Pagination page={currentPage} pages={pages} count={contractRows.length} onChange={setPage}/></section>}
 {tab==='payments'&&<section className="ov-panel"><Head title="Pagos, anticipos y devoluciones" sub="Cada instrucción tiene motivo, aprobaciones y referencia propia"><button disabled={readonly} onClick={()=>setSelection({type:'operation',id:scope.find(c=>contractLimits(s,c,now).payment>0)?.id??scope[0]?.id,kind:'Pago'})}><FontAwesomeIcon icon={faPlus}/> Nueva instrucción</button></Head><div className="fn-kind-tabs">{[['Todas','Todas'],['Pago','Pagos'],['Anticipo','Anticipos'],['Devolución','Devoluciones'],['Garantía','Garantías']].map(([v,label])=><button key={v} className={kind===v?'active':''} onClick={()=>setKind(v)}>{label}</button>)}</div><div className="fn-table-controls"><Search value={search} onChange={setSearch} placeholder="Buscar instrucción o proveedor…"/><select aria-label="Estado de instrucciones financieras" value={status} onChange={e=>setStatus(e.target.value)}>{['Todas','Pendiente de aprobación','Aprobada','Registrada','Cancelada','Rechazada','Fallida'].map(v=><option key={v}>{v}</option>)}</select></div>{requestTable(requestRows)}</section>}
 {tab==='movements'&&<section className="ov-panel"><Head title="Estado de cuenta y movimientos" sub="Distingue impacto en cuenta, reserva interna y pago al beneficiario"><button onClick={downloadStatement}><FontAwesomeIcon icon={faDownload}/> Descargar CSV</button></Head><div className="fn-table-controls"><Search value={search} onChange={setSearch} placeholder="Referencia, contraparte, orden o movimiento…"/><span className="fn-table-count">{movementRows.length} movimientos</span></div><div className="fn-table-scroll"><table className="fn-table"><thead><tr><th>Fecha / referencia</th><th>Movimiento</th><th>Contraparte / orden</th><th>Importe</th><th>Impacto en cuenta</th><th>Conciliación</th><th></th></tr></thead><tbody>{movementRows.slice(0,60).map(m=><tr key={m.id}><td><strong>{date(m.at)}</strong><small>{m.reference}</small></td><td><strong>{m.kind}</strong><small>{m.rail}</small></td><td><span>{m.party}</span><small>{m.orderId??'Cuenta empresa'}</small></td><td><strong>{cash(m.amount)}</strong></td><td><span className={m.walletDelta>0?'fn-value-green':m.walletDelta<0?'fn-value-red':'fn-muted'}>{m.walletDelta>0?'+':''}{m.walletDelta?cash(m.walletDelta):'Sin impacto en cuenta'}</span></td><td><span className={'ov-tag '+(m.reconciled?'green':'blue')}>{m.reconciled?'Conciliada':'Pendiente'}</span></td><td><button className="fn-row-arrow" aria-label={`Ver movimiento ${m.reference}`} onClick={()=>setSelection({type:'movement',id:m.id})}><FontAwesomeIcon icon={faArrowRight}/></button></td></tr>)}</tbody></table></div>{movementRows.length>60&&<p className="fn-note">Se muestran los últimos 60 movimientos. El CSV contiene el estado de cuenta completo con los filtros seleccionados.</p>}</section>}
 {tab==='reconcile'&&<><div className="fn-mini-metrics"><Metric label="Saldo OC en cuenta" value={cash(s.wallet)} sub="Registro de cuenta empresa" color="blue" icon={faWallet}/><Metric label="Saldo según extracto" value={cash(s.statementClosing)} sub={'Corte importado: '+date(s.statementDate)} color="green" icon={faFileInvoice}/><Metric label="Diferencia a revisar" value={cash(s.statementClosing-s.wallet)} sub={`${statementPending.length} movimientos del extracto pendientes`} color="red" icon={faTriangleExclamation}/></div><section className="ov-panel"><Head title="Conciliación de extractos y referencias" sub="La referencia y el importe evitan registrar dos veces el mismo movimiento"><button disabled={readonly} onClick={()=>setSelection({type:'wallet',id:'import'})}><FontAwesomeIcon icon={faPlus}/> Importar extracto CSV</button></Head><div className="fn-table-scroll"><table className="fn-table"><thead><tr><th>Fecha / referencia</th><th>Descripción</th><th>Importe del extracto</th><th>Estado</th><th></th></tr></thead><tbody>{s.statements.map(row=><tr key={row.id}><td><strong>{date(row.date)}</strong><small>{row.reference}</small></td><td>{row.description}</td><td><strong className={row.amount>0?'fn-value-green':'fn-value-red'}>{row.amount>0?'+':''}{cash(row.amount)}</strong></td><td><span className={'ov-tag '+(row.status==='Conciliada'?'green':'blue')}>{row.status}</span></td><td>{row.status==='Pendiente'&&<button disabled={readonly} className="fn-mini-button" onClick={()=>setSelection({type:'statement',id:row.id})}>Conciliar</button>}</td></tr>)}</tbody></table></div></section><section className="ov-panel"><Head title="Pagos informados por las órdenes" sub="Diferencias entre recibos de una orden y su registro de reserva"/>{sourceMismatches.length?sourceMismatches.map(c=><div className="fn-mismatch" key={c.id}><FontAwesomeIcon icon={faTriangleExclamation}/><span><strong>{c.orderId} · {c.supplier}</strong><small>Informado: {cash(c.sourcePaid)} · En reserva: {cash(c.paid)}</small></span><button disabled={readonly||c.sourcePaid<c.paid} className="fn-mini-button" onClick={()=>setSelection({type:'control',id:c.id,control:'source'})}>Revisar diferencia</button></div>):<Empty text="Los pagos informados y los registros de reserva no presentan diferencias."/>}</section></>}
 {tab==='beneficiaries'&&<section className="ov-panel"><Head title="Beneficiarios y destinos autorizados" sub="Titular, referencia de liquidación y revisión administrativa"/><div className="fn-beneficiary-grid">{s.beneficiaries.map(b=><article key={b.id}><span className="fn-party-avatar">{b.name.split(' ').slice(0,2).map(w=>w[0]).join('')}</span><div><h3>{b.name}</h3><span className={'ov-tag '+(b.verified?'green':'red')}>{b.verified?'Revisado en OC':'Revisión pendiente'}</span></div><dl><dt>Destino de registro</dt><dd>{b.destination}</dd><dt>Última revisión</dt><dd>{b.reviewedBy||'Sin responsable'}{b.reviewedAt?' · '+date(b.reviewedAt):''}</dd><dt>Reserva pendiente</dt><dd>{cash(s.contracts.filter(c=>c.supplierSlug===b.id).reduce((n,c)=>n+contractBalance(c),0))}</dd></dl><button className="button secondary" disabled={readonly} onClick={()=>setSelection({type:'beneficiary',id:b.id})}>Revisar destino <FontAwesomeIcon icon={faArrowRight}/></button></article>)}</div></section>}
 {tab==='audit'&&<section className="ov-panel"><Head title="Auditoría de decisiones y saldos" sub="Quién solicitó, quién aprobó, qué cambió y cuál fue el impacto"><button onClick={()=>exportRows('obra-clara-auditoria-'+today,[['Fecha','Responsable','Acción','Entidad','Importe ARGt','Motivo','Saldo antes','Saldo después'],...s.audit.map(a=>[a.at,financeActors.find(u=>u.id===a.actor)?.name??'Sistema',a.action,a.entity,toMajor(a.amount),a.note,toMajor(a.walletBefore),toMajor(a.walletAfter)])])}><FontAwesomeIcon icon={faDownload}/> Exportar auditoría</button></Head><div className="fn-table-scroll"><table className="fn-table"><thead><tr><th>Fecha / hora</th><th>Responsable</th><th>Acción / entidad</th><th>Motivo</th><th>Importe</th><th>Cuenta antes → después</th></tr></thead><tbody>{s.audit.map(a=><tr key={a.id}><td><strong>{date(a.at)}</strong><small>{time(a.at)}</small></td><td>{financeActors.find(u=>u.id===a.actor)?.name??'Sistema'}</td><td><strong>{auditLabel(a.action)}</strong><small>{a.entity}</small></td><td className="fn-note-cell">{a.note}</td><td>{cash(a.amount)}</td><td><strong>{short(a.walletBefore)} → {short(a.walletAfter)}</strong><small>ARGt · cuenta empresa</small></td></tr>)}</tbody></table></div></section>}
 {tab==='rules'&&<><section className="ov-panel"><Head title="Reglas de aprobación y ejecución" sub="Importes, separación de revisiones y límites de la cuenta"/><form className="fn-settings" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act('finance.settings',{threshold:toMinor(Number(f.get('threshold'))),dailyLimit:toMinor(Number(f.get('dailyLimit'))),network:f.get('network'),reason:f.get('reason')});}}><div className="fn-form-grid"><label>Una aprobación hasta (ARGt)<input name="threshold" type="number" min="0.01" step="0.01" defaultValue={toMajor(s.settings.threshold)} required disabled={actor!=='ma'}/></label><label>Límite diario de pagos (ARGt)<input name="dailyLimit" type="number" min="0.01" step="0.01" defaultValue={toMajor(s.settings.dailyLimit)} required disabled={actor!=='ma'}/></label><label>Red a validar en la conexión<select name="network" defaultValue={s.settings.network} disabled={actor!=='ma'}>{['Base','Polygon','Arbitrum','Ethereum'].map(n=><option key={n}>{n}</option>)}</select></label><label>Motivo de la actualización<input name="reason" minLength={8} maxLength={1000} placeholder="Describí por qué cambia la política" required disabled={actor!=='ma'}/></label></div><div className="fn-policy-summary"><p><FontAwesomeIcon icon={faUserCheck}/><strong>Hasta {cash(s.settings.threshold)}:</strong> una aprobación. Por encima: dos personas distintas.</p><p><FontAwesomeIcon icon={faLock}/> Una reserva pausada o en disputa no admite pagos. El saldo se controla de nuevo antes de registrar la ejecución.</p><p><FontAwesomeIcon icon={faCheckDoubleSafe}/> Cada instrucción tiene una referencia única. Cancelarla sólo es posible antes de su registro.</p></div>{actor!=='ma'&&<p className="fn-note">La edición de esta política corresponde a Dirección financiera.</p>}<button className="button primary" disabled={busy||actor!=='ma'}>Guardar política</button></form></section><section className="ov-panel"><Head title="Cuenta, activo y contrato: tres capas distintas" sub="El registro operativo no reemplaza la confirmación del proveedor ni de la red"/><div className="fn-connections"><article><span className="fn-connection-icon"><FontAwesomeIcon icon={faWallet}/></span><div><h3>Belo · Cuenta empresa</h3><p>Saldos, depósitos, retiros, conversión y referencias de la cuenta.</p><span className="ov-tag neutral">Sin vincular</span></div><button className="fn-mini-button" onClick={()=>setSelection({type:'wallet'})}>Ver requisitos</button></article><article><span className="fn-connection-icon blue"><FontAwesomeIcon icon={faArrowRightArrowLeft}/></span><div><h3>Twin · ARGt</h3><p>Activo de referencia. Red configurada: {s.settings.network}. La ruta de ingreso y egreso debe validarse con la cuenta.</p><span className="ov-tag blue">ARGt · referencia de activo</span></div><a href="https://docs.twin.finance/" target="_blank" rel="noreferrer">Documentación <FontAwesomeIcon icon={faArrowUpRightFromSquare}/></a></article><article><span className="fn-connection-icon green"><FontAwesomeIcon icon={faLock}/></span><div><h3>Reserva de Obra Clara</h3><p>Reglas por orden, anticipos, recepción, garantías y devolución del saldo no entregado.</p><span className="ov-tag neutral">Dirección de despliegue pendiente</span></div></article><article><span className="fn-connection-icon"><FontAwesomeIcon icon={faRotate}/></span><div><h3>Confirmaciones y conciliación</h3><p>La aprobación administrativa, el registro contable y la confirmación externa se monitorean por separado.</p><span className="ov-tag neutral">Sin eventos externos recibidos</span></div></article></div></section></>}
 <footer className="fn-footer"><span><FontAwesomeIcon icon={faLock}/> Cuenta, reserva y beneficiario con trazabilidad por instrucción.</span><button onClick={()=>switchTab('audit')}>Ver auditoría <FontAwesomeIcon icon={faArrowRight}/></button></footer>
 <dialog ref={dialog} className="fn-dialog" onCancel={()=>setSelection(null)} onClick={e=>{if(e.target===e.currentTarget)setSelection(null);}}><header><span>CONTROL DE FONDOS</span><button aria-label="Cerrar panel de fondos" onClick={()=>setSelection(null)}><FontAwesomeIcon icon={faXmark}/></button></header>{error&&<p role="alert" className="fn-error">{error}</p>}
 {selection?.type==='contract'&&selectedContract&&<ContractDetail s={s} c={selectedContract} now={now} readonly={readonly} onSelect={setSelection} onAsk={()=>askBrick(selectedContract)}/>}
 {(selection?.type==='operation'||selection?.type==='fund')&&<OperationForm s={s} initialContract={selectedContract} kind={selection.kind??'Pago'} fund={selection.type==='fund'} now={now} busy={busy} readonly={readonly} onSubmit={(contractId,kind,amount,reason)=>void act(selection.type==='fund'?'finance.fund':'finance.request',{contractId,kind,amount,reason})}/>}
 {selection?.type==='request'&&selectedRequest&&<RequestDetail s={s} request={selectedRequest} now={now} actor={actor} actorSelect={actorSelect} busy={busy} readonly={readonly} onAct={(type,payload,keep)=>void act(type,payload,keep)} onContract={id=>setSelection({type:'contract',id})}/>}
 {selection?.type==='control'&&selectedContract&&<ControlForm c={selectedContract} control={selection.control!} busy={busy} readonly={readonly} onSubmit={reason=>{const control=selection.control;const type=control==='pause'?'finance.pause':control==='dispute'?'finance.dispute':control==='source'?'finance.source.reconcile':'finance.advance.cancel';void act(type,{contractId:selectedContract.id,paused:!selectedContract.paused,disputed:!selectedContract.disputed,reason});}}/>}
 {selection?.type==='beneficiary'&&selectedBeneficiary&&<form className="fn-dialog-content fn-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act('finance.beneficiary',{beneficiaryId:selectedBeneficiary.id,destination:f.get('destination'),verified:f.get('verified')==='on',reason:f.get('reason')});}}><h2>Revisar destino de liquidación</h2><p className="fn-subtitle">{selectedBeneficiary.name}</p><label>Referencia del destino<input name="destination" defaultValue={selectedBeneficiary.destination} minLength={5} maxLength={180} required/></label><label className="fn-check"><input name="verified" type="checkbox" defaultChecked={selectedBeneficiary.verified}/> Validé la titularidad y la moneda del destino para el registro en OC.</label><label>Motivo o documentación revisada<textarea name="reason" rows={3} minLength={8} maxLength={1000} required placeholder="Dejá constancia de la revisión realizada"/></label><button className="button primary" disabled={busy||readonly}>Guardar revisión</button><p className="fn-note">La revisión administrativa de OC no certifica una cuenta en Belo ni ejecuta una transferencia.</p></form>}
 {selection?.type==='wallet'&&<WalletDialog s={s} mode={selection.id??'deposit'} busy={busy} readonly={readonly} onRules={()=>{setSelection(null);switchTab('rules');}} onImport={(rows,closingBalance)=>void act('finance.statement.import',{rows,closingBalance,reason:'Importación de extracto para conciliación administrativa.'})}/>}
 {selection?.type==='statement'&&selectedStatement&&<form className="fn-dialog-content fn-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void act('finance.reconcile',{statementId:selectedStatement.id,movementId:f.get('movementId')||undefined,reason:f.get('reason')});}}><span className="ov-tag blue">Pendiente de conciliación</span><h2>{selectedStatement.reference}</h2><p className="fn-subtitle">{selectedStatement.description}</p><div className="fn-operation-summary"><span>Importe del extracto</span><strong>{selectedStatement.amount>0?'+':''}{cash(selectedStatement.amount)}</strong></div><label>Vincular o registrar<select name="movementId"><option value="">Registrar ajuste en cuenta OC</option>{s.movements.filter(m=>!m.reconciled&&m.walletDelta===selectedStatement.amount).map(m=><option key={m.id} value={m.id}>Vincular {m.reference} · {cash(m.walletDelta)}</option>)}</select></label><p className="fn-callout">Si vinculás un movimiento existente, el saldo no vuelve a modificarse. Un ajuste nuevo impacta en el saldo registrado y queda identificado en Auditoría.</p><label>Motivo de conciliación<textarea name="reason" minLength={8} maxLength={1000} rows={3} required placeholder="Referencia cotejada y diferencia que se está registrando"/></label><button className="button primary" disabled={busy||readonly}>Confirmar conciliación</button></form>}
 {selection?.type==='movement'&&selectedMovement&&<div className="fn-dialog-content"><span className={'ov-tag '+(selectedMovement.reconciled?'green':'blue')}>{selectedMovement.reconciled?'Conciliada':'Por conciliar'}</span><h2>{selectedMovement.kind}</h2><p className="fn-subtitle">{selectedMovement.reference}</p><div className="fn-operation-summary"><span>Importe</span><strong>{cash(selectedMovement.amount)}</strong></div><Details rows={[["Fecha",date(selectedMovement.at)+' · '+time(selectedMovement.at)],["Contraparte",selectedMovement.party],["Orden",selectedMovement.orderId??'Cuenta empresa'],["Impacto en cuenta",cash(selectedMovement.walletDelta)],["Fuente",selectedMovement.rail],["Emisión a red","Sin referencia externa registrada"]]}/><div className="fn-dialog-actions">{selectedMovement.contractId&&<button className="button secondary" onClick={()=>setSelection({type:'contract',id:selectedMovement.contractId})}>Abrir reserva</button>}<button className="button primary" onClick={()=>exportRows(selectedMovement.reference,[['Referencia','Tipo','Importe ARGt','Impacto en cuenta','Fecha','Orden'],[selectedMovement.reference,selectedMovement.kind,toMajor(selectedMovement.amount),toMajor(selectedMovement.walletDelta),selectedMovement.at,selectedMovement.orderId??'']])}><FontAwesomeIcon icon={faDownload}/> Descargar comprobante CSV</button></div></div>}
 </dialog>{toast&&<div className="fn-toast" role="status"><FontAwesomeIcon icon={faCheck}/>{toast}</div>}{error&&!selection&&<p role="alert" className="fn-error">{error}</p>}</div>;
}
const faCheckDoubleSafe=faCheck;
function Metric({label,value,sub,color,icon,onClick}:{label:string;value:string;sub:string;color:string;icon:typeof faWallet;onClick?:()=>void}){return <button type="button" className={'fn-metric '+color} onClick={onClick} disabled={!onClick}><span>{label}<i><FontAwesomeIcon icon={icon}/></i></span><strong>{value}</strong><small>{sub}</small></button>;}
function Head({title,sub,children}:{title:string;sub:string;children?:React.ReactNode}){return <header className="ov-panel-head"><div><h3>{title}</h3><p>{sub}</p></div>{children}</header>;}
function Empty({text}:{text:string}){return <p className="fn-empty">{text}</p>;}
function Search({value,onChange,placeholder}:{value:string;onChange:(s:string)=>void;placeholder:string}){return <label className="fn-search"><FontAwesomeIcon icon={faMagnifyingGlass}/><input aria-label={placeholder} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/></label>;}
function Pagination({page,pages,count,onChange}:{page:number;pages:number;count:number;onChange:(p:number)=>void}){return <div className="fn-pagination"><span>{count?`${(page-1)*10+1}–${Math.min(page*10,count)}`:'0'} de {count} contratos</span><div>{[[1,'«','Primera página'],[page-1,'‹','Página anterior'],[page+1,'›','Página siguiente'],[pages,'»','Última página']].map(([n,label,aria],i)=><button key={String(aria)} aria-label={String(aria)} disabled={i<2?page===1:page===pages} onClick={()=>onChange(Number(n))}>{label}</button>)}<small>{page} / {pages}</small></div></div>;}
function Details({rows}:{rows:[string,string][]}){return <dl className="fn-details">{rows.map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>;}
function auditLabel(action:string){return ({'finance.request':'Instrucción creada','finance.approve':'Aprobación registrada','finance.execute':'Ejecución registrada','finance.cancel':'Instrucción cancelada','finance.reject':'Instrucción rechazada','finance.retry':'Instrucción reabierta','finance.fund':'Fondeo de reserva','finance.pause':'Control de pausa','finance.dispute':'Gestión de disputa','finance.advance.cancel':'Anticipo cancelado','finance.reconcile':'Conciliación','finance.source.reconcile':'Pago informado conciliado','finance.beneficiary':'Revisión de beneficiario','finance.settings':'Política actualizada','finance.statement.import':'Extracto importado'} as Record<string,string>)[action]??action;}
function CapitalChart({available,reserved,queued}:{available:number;reserved:number;queued:number}){const total=available+reserved;const parts=[{label:'Disponible',value:available,color:'green'},{label:'Reserva sin instrucciones',value:Math.max(0,reserved-queued),color:'blue'},{label:'En instrucciones',value:queued,color:'orange'}];let offset=0;return <div className="fn-capital-chart"><div className="fn-donut"><svg viewBox="0 0 150 150" role="img" aria-label={parts.map(p=>p.label+': '+cash(p.value)).join(', ')}><circle cx="75" cy="75" r="58" fill="none" stroke="#eee" strokeWidth="14"/>{parts.map(p=>{const len=total?p.value/total*364.425:0;const before=offset;offset+=len;return <circle key={p.label} className={'fn-stroke-'+p.color} cx="75" cy="75" r="58" fill="none" strokeWidth="14" strokeDasharray={`${Math.max(0,len-2)} ${364.425-Math.max(0,len-2)}`} strokeDashoffset={-before} transform="rotate(-90 75 75)"/>;})}</svg><div><strong>{short(total)}</strong><small>ARGt controlados</small></div></div><div className="fn-capital-legend">{parts.map(p=><div key={p.label}><i className={'ov-dot '+p.color}/><span>{p.label}</span><strong>{short(p.value)} ARGt</strong></div>)}</div></div>;}
function CashFlow({s,today}:{s:FinanceState;today:string}){const days=Array.from({length:7},(_,i)=>{const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-6+i);const day=d.toISOString().slice(0,10);const movements=s.movements.filter(m=>financeToday(m.at)===day&&m.kind!=='Apertura de registros');return {day,in:movements.filter(m=>m.walletDelta>0).reduce((n,m)=>n+m.walletDelta,0),out:movements.filter(m=>m.walletDelta<0).reduce((n,m)=>n-m.walletDelta,0)};});const max=Math.max(1,...days.map(d=>Math.max(d.in,d.out)));return <><div className="fn-flow-chart">{days.map(d=><div key={d.day} title={`${date(d.day)} · Entradas: ${cash(d.in)} · Fondeos/cargos: ${cash(d.out)}`}><span><i className="green" style={{height:Math.max(1,d.in/max*100)+'%'}}/><i className="blue" style={{height:Math.max(1,d.out/max*100)+'%'}}/></span><small>{date(d.day)}</small></div>)}</div><div className="fn-flow-legend"><span><i className="ov-dot green"/> Ingresos y reintegros</span><span><i className="ov-dot blue"/> Fondeos de reservas y cargos</span></div></>;}
function ContractDetail({s,c,now,readonly,onSelect,onAsk}:{s:FinanceState;c:FinanceContract;now:string;readonly:boolean;onSelect:(v:Selection)=>void;onAsk:()=>void}){const l=contractLimits(s,c,now);const requests=s.requests.filter(r=>r.contractId===c.id);return <div className="fn-dialog-content"><span className={'ov-tag '+(l.blocked?'red':'blue')}>{contractStatus(c,s,now)}</span><h2>{c.orderId}</h2><p className="fn-subtitle">{c.project} · {c.supplier}</p><p>{c.item}</p><div className="fn-detail-metrics"><div><span>Reserva disponible</span><strong>{cash(l.balance)}</strong></div><div><span>Habilitado para pago</span><strong>{cash(l.payment)}</strong></div><div><span>Instrucciones en curso</span><strong>{cash(l.pending)}</strong></div></div><Details rows={[["Orden / fondeado",cash(c.principal)+' / '+cash(c.funded)],["Recepción validada",cash(c.receivedValue)],["Recepción informada",cash(c.reportedValue)],["Pagado al proveedor",cash(c.paid)],["Anticipo liquidado / máximo",cash(c.advancePaid)+' / '+cash(c.advanceLimit)],["Saldo devuelto",cash(c.refunded)],["Garantía retenida",cash(l.retained)],["Entrega comprometida",date(c.due)+' · '+c.graceHours+' h de tolerancia'],["Garantía hasta",date(c.warrantyEnd)]]}/>{l.blocked&&<p className="fn-error">{c.disputed?'Reserva en disputa: '+c.disputeNote:'Reserva pausada.'} Las instrucciones de salida están bloqueadas.</p>}<h3>Gestionar la reserva</h3><div className="fn-action-grid">{(['Pago','Anticipo','Devolución','Garantía'] as FinanceKind[]).map(k=><button className="fn-action-card" key={k} disabled={readonly} onClick={()=>onSelect({type:'operation',id:c.id,kind:k})}><FontAwesomeIcon icon={k==='Devolución'?faRotate:k==='Garantía'?faShieldHalved:faArrowUp}/><span><strong>{k==='Pago'?'Liberar pago':k==='Anticipo'?'Liberar anticipo':k==='Devolución'?'Solicitar devolución':'Liberar garantía'}</strong><small>Habilitado: {cash(amountLimit(s,c,k,now))}</small></span></button>)}</div><div className="fn-callout">La devolución reintegra a la cuenta empresa sólo el saldo que no corresponde a entregas recibidas o anticipos ya liquidados. Se habilita al vencer el plazo de entrega y su tolerancia, o al cancelar comercialmente la orden.</div>{c.advancePaid>c.receivedValue&&<p className="fn-error">Anticipo expuesto: {cash(c.advancePaid-c.receivedValue)}. Este importe ya fue liquidado; requiere un reclamo al proveedor y no puede cancelarse como saldo retenido.</p>}<div className="fn-dialog-actions"><button className="button secondary" disabled={readonly||c.funded>=c.principal} onClick={()=>onSelect({type:'fund',id:c.id})}>Asignar fondos</button><button className="button secondary" disabled={readonly} onClick={()=>onSelect({type:'control',id:c.id,control:'pause'})}><FontAwesomeIcon icon={c.paused?faPlay:faPause}/>{c.paused?'Reanudar':'Pausar reserva'}</button><button className="button secondary" disabled={readonly} onClick={()=>onSelect({type:'control',id:c.id,control:'dispute'})}>{c.disputed?'Resolver disputa':'Abrir disputa'}</button><button className="button secondary" disabled={readonly||c.advanceCanceled||c.advancePaid>0} onClick={()=>onSelect({type:'control',id:c.id,control:'cancelAdvance'})}>{c.advanceCanceled?'Anticipo cancelado':'Cancelar anticipo pendiente'}</button><button className="button secondary" onClick={onAsk}><FontAwesomeIcon icon={faRobot}/> Revisar con Brick</button>{c.live&&<Link className="button secondary" href={'/compras?orden='+encodeURIComponent(c.orderId)}>Ver orden →</Link>}</div><h3>Instrucciones de esta reserva</h3>{requests.length?<div className="fn-request-list">{requests.map(r=><button key={r.id} onClick={()=>onSelect({type:'request',id:r.id})}><span>{r.kind}<small>{r.id}</small></span><strong>{cash(r.amount)}</strong><span className={'ov-tag '+stateTone(r.status)}>{r.status}</span></button>)}</div>:<p className="fn-note">Todavía no hay instrucciones para esta reserva.</p>}<details className="fn-technical"><summary>Identificación técnica y trazabilidad</summary><Details rows={[["ID interno",c.id],["Activo / red configurada",'ARGt / '+s.settings.network],["Contrato en red",'Dirección de despliegue pendiente'],["Cuenta externa",'Sin vinculación de Belo'],["Eventos",'Registro OC; sin confirmación externa'] ]}/></details><h3>Historial de movimientos</h3><div className="fn-timeline">{s.movements.filter(m=>m.contractId===c.id).map(m=><div key={m.id}><i/><span><strong>{m.kind}</strong><small>{date(m.at)} · {m.reference}</small></span><b>{cash(m.amount)}</b></div>)}</div></div>;}
function OperationForm({s,initialContract,kind:initialKind,fund,now,busy,readonly,onSubmit}:{s:FinanceState;initialContract?:FinanceContract;kind:FinanceKind;fund:boolean;now:string;busy:boolean;readonly:boolean;onSubmit:(id:string,k:FinanceKind,a:number,r:string)=>void}){const [id,setId]=useState(initialContract?.id??s.contracts[0]?.id??'');const [kind,setKind]=useState(initialKind);const c=s.contracts.find(c=>c.id===id);if(!c)return <Empty text="Creá una orden asignada a un proyecto antes de operar."/>;const l=contractLimits(s,c,now);const max=fund?(c.paused||c.disputed||c.commercialCanceled?0:Math.min(s.wallet,c.principal-c.funded)):amountLimit(s,c,kind,now);const beneficiary=s.beneficiaries.find(b=>b.id===c.supplierSlug);const invalid=!fund&&kind!=='Devolución'&&!beneficiary?.verified;return <form className="fn-dialog-content fn-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSubmit(c.id,kind,toMinor(Number(f.get('amount'))),String(f.get('reason')));}}><h2>{fund?'Asignar fondos a una reserva':'Nueva instrucción de '+kind.toLowerCase()}</h2><p className="fn-subtitle">Cada instrucción conserva su motivo, responsables y referencia.</p><label>Reserva y proyecto<select value={id} onChange={e=>setId(e.target.value)}>{s.contracts.map(c=><option key={c.id} value={c.id}>{c.orderId} · {c.project} · {c.supplier}</option>)}</select></label>{!fund&&<label>Tipo de instrucción<select value={kind} onChange={e=>setKind(e.target.value as FinanceKind)}>{['Pago','Anticipo','Devolución','Garantía'].map(k=><option key={k}>{k}</option>)}</select></label>}<div className="fn-operation-summary"><span>Máximo habilitado ahora</span><strong>{cash(max)}</strong></div><Details rows={[["Origen",fund?'Cuenta empresa · saldo disponible':'Reserva '+c.orderId],["Destino",fund?c.project:kind==='Devolución'?'Cuenta empresa':c.supplier],["Saldo de la reserva",cash(l.balance)],["Pendiente de instrucciones",cash(l.pending)]]}/>{!max&&<p className="fn-error">{l.blocked?'La reserva está pausada o en disputa.':fund?'La orden ya está fondeada o no tiene saldo disponible.':kind==='Anticipo'?c.advancePaid?'El anticipo ya fue liquidado o el cupo está comprometido.':'No hay anticipo habilitado para esta reserva.':kind==='Devolución'?'La devolución no está habilitada por plazo, recepción o saldo disponible.':kind==='Garantía'?'La garantía requiere recepción completa y vencimiento de su plazo.':'No hay recepción validada pendiente de pago; revisá las instrucciones existentes.'}</p>}{invalid&&<p className="fn-error">Revisá y validá el destino del beneficiario antes de solicitar una salida.</p>}<label>Importe ARGt<input key={id+kind+fund} name="amount" type="number" min="0.01" step="0.01" max={toMajor(max)} defaultValue={toMajor(max)} required/></label><label>Motivo<textarea name="reason" minLength={8} maxLength={1000} rows={3} required placeholder="Entrega o condición que respalda esta instrucción"/></label><p className="fn-callout">{fund?'El importe pasa del saldo disponible a la reserva de esta orden.':'La instrucción requiere '+(max>s.settings.threshold?'hasta dos aprobaciones según el importe':'una aprobación')+'. La ejecución se registra por separado y vuelve a validar saldo y condiciones.'} El registro no emite una transferencia a Belo ni a la red.</p><button className="button primary" disabled={busy||readonly||max<=0||invalid}>{busy?'Guardando…':fund?'Asignar fondos':'Crear instrucción'}</button></form>;}
function RequestDetail({s,request:r,now,actor,actorSelect,busy,readonly,onAct,onContract}:{s:FinanceState;request:FinanceRequest;now:string;actor:string;actorSelect:ReactNode;busy:boolean;readonly:boolean;onAct:(type:string,p:Record<string,unknown>,keep?:boolean)=>void;onContract:(id:string)=>void}){const [reason,setReason]=useState('');const c=s.contracts.find(c=>c.id===r.contractId)!;const l=contractLimits(s,c,now,r.id);const cap=r.kind==='Pago'?l.payment:r.kind==='Anticipo'?l.advance:r.kind==='Devolución'?l.refund:l.guarantee;const active=['Pendiente de aprobación','Aprobada','Fallida'].includes(r.status);return <div className="fn-dialog-content fn-form"><span className={'ov-tag '+stateTone(r.status)}>{r.status}</span><h2>{r.kind} · {cash(r.amount)}</h2><p className="fn-subtitle">{r.id}</p><Details rows={[["Proyecto",c.project],["Proveedor",c.supplier],["Destino",r.kind==='Devolución'?'Cuenta empresa':s.beneficiaries.find(b=>b.id===c.supplierSlug)?.destination??'Sin revisar'],["Orden",c.orderId],["Creada",date(r.createdAt)+' · '+time(r.createdAt)],["Motivo",r.reason],["Capacidad actual",cash(cap)]]}/><button className="fn-text-button" onClick={()=>onContract(c.id)}>Abrir reserva →</button><h3>Aprobaciones {r.approvals.length} / {requiredApprovals(s,r.amount)}</h3><div className="fn-approval-list">{r.approvals.map(a=><div key={a.actor}><FontAwesomeIcon icon={faCircleCheck}/><span>{financeActors.find(x=>x.id===a.actor)?.name}<small>{date(a.at)} · {time(a.at)}</small></span></div>)}{r.approvals.length===0&&<p className="fn-note">Ninguna aprobación registrada.</p>}</div>{active&&actorSelect}{active&&(l.blocked||r.amount>cap)&&<p className="fn-error">Las condiciones cambiaron o existe un bloqueo. Revisá la reserva antes de continuar.</p>}{r.failure&&<p className="fn-error">{r.failure}</p>}<div className="fn-dialog-actions">{r.status==='Pendiente de aprobación'&&<button className="button primary" disabled={busy||readonly||r.approvals.some(a=>a.actor===actor)||l.blocked||r.amount>cap} onClick={()=>onAct('finance.approve',{requestId:r.id},true)}>Registrar aprobación</button>}{r.status==='Aprobada'&&<button className="button primary" disabled={busy||readonly||l.blocked||r.amount>cap} onClick={()=>onAct('finance.execute',{requestId:r.id},true)}>Registrar ejecución</button>}</div>{active&&<><label>Motivo de cancelación, rechazo o revisión<textarea value={reason} onChange={e=>setReason(e.target.value)} rows={2} minLength={8} maxLength={1000} placeholder="Dejá constancia de la decisión"/></label><div className="fn-dialog-actions"><button className="button secondary" disabled={busy||readonly||reason.trim().length<8} onClick={()=>onAct('finance.cancel',{requestId:r.id,reason},true)}>Cancelar instrucción</button><button className="button secondary" disabled={busy||readonly||reason.trim().length<8} onClick={()=>onAct('finance.reject',{requestId:r.id,reason},true)}>Rechazar</button>{r.status==='Fallida'&&<button className="button secondary" disabled={busy||readonly||reason.trim().length<8||l.blocked||r.amount>cap} onClick={()=>onAct('finance.retry',{requestId:r.id,reason},true)}>Revisar y pedir aprobación otra vez</button>}</div></>}{r.status==='Registrada'&&<><div className="fn-callout"><strong>Registro OC: {r.reference}</strong><p>Registrado {r.registeredAt&&date(r.registeredAt)}. Emisión a red: sin emitir. Una instrucción registrada no se puede cancelar como una pendiente.</p></div><button className="button secondary" onClick={()=>exportRows(r.reference??r.id,[['Referencia','Orden','Tipo','Importe ARGt','Fecha','Estado','Fuente'],[r.reference??r.id,c.orderId,r.kind,toMajor(r.amount),r.registeredAt??'',r.status,'Registro OC']])}><FontAwesomeIcon icon={faDownload}/> Descargar comprobante</button></>}</div>;}
function ControlForm({c,control,busy,readonly,onSubmit}:{c:FinanceContract;control:NonNullable<Selection['control']>;busy:boolean;readonly:boolean;onSubmit:(reason:string)=>void}){const title=control==='pause'?(c.paused?'Reanudar reserva':'Pausar reserva'):control==='dispute'?(c.disputed?'Resolver disputa':'Abrir disputa'):control==='source'?'Conciliar pago informado':'Cancelar anticipo pendiente';return <form className="fn-dialog-content fn-form" onSubmit={e=>{e.preventDefault();onSubmit(String(new FormData(e.currentTarget).get('reason')));}}><h2>{title}</h2><p className="fn-subtitle">{c.orderId} · {c.project}</p><p className="fn-callout">{control==='pause'?'Una pausa bloquea las instrucciones de salida y los nuevos fondeos. El saldo permanece en la reserva.':control==='dispute'?'La disputa conserva el saldo y bloquea las salidas hasta que se resuelva con un motivo documentado.':control==='source'?'Se incorporará el pago informado desde la orden: '+cash(c.sourcePaid-c.paid)+'. Las instrucciones abiertas se enviarán a revisión para evitar duplicaciones.':'Se cancela el anticipo que todavía no fue liquidado. El dinero sigue reservado para la orden y puede utilizarse bajo sus condiciones.'}</p>{control==='cancelAdvance'&&c.advancePaid>0&&<p className="fn-error">Un anticipo liquidado no puede cancelarse. Abrí una disputa para gestionar su recuperación con el proveedor.</p>}<label>Motivo y referencia<textarea name="reason" rows={4} minLength={8} maxLength={1000} required placeholder="Explicá la decisión y la documentación revisada"/></label><button className="button primary" disabled={busy||readonly||control==='cancelAdvance'&&c.advancePaid>0}>{title}</button></form>;}
function parseStatement(raw:string):FinanceStatement[]{const lines=raw.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<2||lines.length>201)throw new Error('Usá un CSV de 1 a 200 movimientos.');const delimiter=lines[0].includes(';')?';':',';const fields=(line:string)=>{const result:string[]=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(ch===delimiter&&!quoted){result.push(value.trim());value='';}else value+=ch;}if(quoted)throw new Error('Hay comillas sin cerrar en el CSV.');result.push(value.trim());return result;};const headers=fields(lines[0]).map(x=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''));for(const h of ['fecha','referencia','importe','moneda'])if(!headers.includes(h))throw new Error('Falta la columna '+h+'.');return lines.slice(1).filter(Boolean).map((line,i)=>{const values=fields(line);const get=(key:string)=>values[headers.indexOf(key)]??'';const date=get('fecha');const amountRaw=get('importe');const normalized=amountRaw.includes(',')?amountRaw.replace(/\./g,'').replace(',','.'):amountRaw;const number=Number(normalized);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||new Date(date+'T12:00:00Z').toISOString().slice(0,10)!==date||!get('referencia')||get('moneda')!=='ARGt'||!/^[-+]?\d+(\.\d{1,2})?$/.test(normalized)||!Number.isFinite(number)||number===0)throw new Error('Revisá fecha, referencia, importe y moneda en la fila '+(i+2)+'.');return {id:'IMPORT-'+i,date,reference:get('referencia'),amount:toMinor(number),currency:'ARGt',description:get('descripcion')||'Movimiento importado',status:'Pendiente'};});}
function WalletDialog({s,mode,busy,readonly,onRules,onImport}:{s:FinanceState;mode:string;busy:boolean;readonly:boolean;onRules:()=>void;onImport:(rows:FinanceStatement[],closingBalance?:number)=>void}){const [rows,setRows]=useState<FinanceStatement[]>([]);const [error,setError]=useState('');return <div className="fn-dialog-content fn-form"><span className="ov-tag blue">Cuenta empresa · ARGt</span><h2>{mode==='import'?'Importar extracto':mode==='transfer'?'Transferir fondos':mode==='convert'?'Convertir saldo':'Ingresar fondos'}</h2>{mode==='import'?<form className="fn-form" onSubmit={e=>{e.preventDefault();const value=String(new FormData(e.currentTarget).get('closing')??'');onImport(rows,value?toMinor(Number(value)):undefined);}}><p>Importá movimientos para cotejarlos con el registro de cuenta. La importación no modifica el saldo; cada diferencia se concilia por separado.</p><button type="button" className="button secondary" onClick={()=>exportRows('plantilla-extracto',[['fecha','referencia','importe','moneda','descripcion'],[financeToday(new Date().toISOString()),'REFERENCIA-UNICA','1250000.00','ARGt','Ingreso cuenta empresa']])}>Descargar plantilla CSV</button><label>Archivo CSV<input type="file" accept=".csv,text/csv" required onChange={async e=>{setError('');setRows([]);const f=e.target.files?.[0];if(!f)return;if(f.size>500000){setError('El archivo supera 500 KB.');return;}try{setRows(parseStatement(await f.text()));}catch(err){setError(err instanceof Error?err.message:'No se pudo leer el extracto.');}}}/></label>{error&&<p className="fn-error" role="alert">{error}</p>}{rows.length>0&&<div className="fn-callout"><strong>{rows.length} movimientos listos</strong>{rows.slice(0,4).map((r,i)=><p key={i}>{r.reference} · {cash(r.amount)} · {date(r.date)}</p>)}</div>}<label>Saldo de cierre del extracto ARGt (opcional)<input name="closing" type="number" min="0" step="0.01"/></label><button className="button primary" disabled={busy||readonly||!rows.length}>Importar para conciliación</button></form>:<><p className="fn-subtitle">Prepará la vinculación de la cuenta para habilitar esta operación.</p><div className="fn-operation-summary"><span>Disponible en el registro OC</span><strong>{cash(s.wallet)}</strong></div><Details rows={[["Cuenta Belo",'Sin vincular'],["Saldo externo",'Sin lectura'],["Activo",'ARGt'],["Red configurada",s.settings.network],["Dirección / CVU",'Pendiente de validación con la cuenta'],["Transferencia",'Sin emitir'] ]}/><p className="fn-callout">La conexión debe validar titularidad, monedas, red y destino. Luego se podrán consultar saldos externos, crear la instrucción y seguir su confirmación. Las credenciales y firmas se gestionan del lado del servidor.</p><button className="button primary" onClick={onRules}>Ver reglas y conexión →</button></>}</div>;}
